-- Per-minute scheduler for Skii Pronos alerts (Supabase pg_cron + pg_net).
-- Run once in Supabase → SQL editor. Safe to re-run: cron.schedule replaces a job with the same name.

-- 1. Extensions (the Database → Extensions toggles do the same thing).
create extension if not exists pg_cron;
create extension if not exists pg_net;
grant usage on schema cron to postgres;
grant all privileges on all tables in schema cron to postgres;

-- 2. Call /api/tick every minute. The tick secret lives in skii_config (key tick_secret),
--    generated by the site itself, so nothing secret is written in this file.
select cron.schedule(
  'skii-tick',
  '* * * * *',
  $$
  select net.http_get(
    url := 'https://skii-pronos.vercel.app/api/tick?key='
        || (select value #>> '{}' from public.skii_config where key = 'tick_secret'),
    timeout_milliseconds := 30000
  );
  $$
);

-- 3. Keep the cron log small (pg_net already drops its own responses after 6 hours).
select cron.schedule(
  'skii-tick-cleanup',
  '0 3 * * *',
  $$ delete from cron.job_run_details where end_time < now() - interval '7 days' $$
);

-- Check (after a minute or two):
--   select jobid, jobname, schedule, active from cron.job;
--   select status, return_message, start_time from cron.job_run_details order by start_time desc limit 5;
--   select status_code, created, left(content::text, 160) from net._http_response order by created desc limit 5;
-- or open https://skii-pronos.vercel.app/api/tick?health → "running": true.

-- To stop:  select cron.unschedule('skii-tick');  select cron.unschedule('skii-tick-cleanup');
